<template><section class="page-card"><div class="page-header"><div><h1 class="page-title">用户中心</h1><p class="muted">维护当前登录账号的显示名称和密码。</p></div></div><el-row :gutter="24"><el-col :md="12"><h3>基本资料</h3><el-descriptions :column="1" border><el-descriptions-item label="用户名">{{ user.profile?.username }}</el-descriptions-item><el-descriptions-item label="角色">{{ user.profile?.roles?.map(r=>r.roleName).join('、') || '-' }}</el-descriptions-item></el-descriptions><el-form class="drawer-form" :model="profileForm"><el-form-item label="显示名称"><el-input v-model="profileForm.displayName" /></el-form-item><el-button type="primary" :loading="profileLoading" @click="saveProfile">保存资料</el-button></el-form></el-col><el-col :md="12"><h3>修改密码</h3><el-alert title="修改成功后，其他已登录会话将被注销。" type="info" :closable="false" /><el-form class="drawer-form" :model="passwordForm"><el-form-item label="当前密码"><el-input v-model="passwordForm.currentPassword" type="password" show-password /></el-form-item><el-form-item label="新密码"><el-input v-model="passwordForm.newPassword" type="password" show-password /></el-form-item><el-button v-has-permi="'system:profile:change-password'" type="primary" :loading="passwordLoading" @click="savePassword">修改密码</el-button></el-form></el-col></el-row></section></template>
<script setup>import { reactive,watch,ref } from 'vue'; import { ElMessage } from 'element-plus'; import { useUserStore } from '@/stores/user'; const user=useUserStore(), profileLoading=ref(false),passwordLoading=ref(false);const profileForm=reactive({displayName:''}),passwordForm=reactive({currentPassword:'',newPassword:''});watch(()=>user.profile,(p)=>profileForm.displayName=p?.displayName||'',{immediate:true});async function saveProfile(){profileLoading.value=true;try{await user.updateProfile(profileForm);ElMessage.success('资料已更新。')}catch(e){ElMessage.error(e.message)}finally{profileLoading.value=false}}async function savePassword(){if(!passwordForm.currentPassword||passwordForm.newPassword.length<8)return ElMessage.warning('请填写当前密码及至少 8 位新密码。');passwordLoading.value=true;try{await user.changePassword(passwordForm);passwordForm.currentPassword='';passwordForm.newPassword='';ElMessage.success('密码已修改。')}catch(e){ElMessage.error(e.message)}finally{passwordLoading.value=false}}</script>
